@Test
public void testTimeout() {
    Thread[] pool = new Thread[50];
    for (int i = 0; i < pool.length; i++) {
        pool[i] = new Thread(new Worker(i, 5, 3));
    }
    for (int i = 0; i < pool.length; i++) {
        pool[i].start();
    }
    for (int i = 0; i < pool.length; i++) {
        try {
            pool[i].join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

